macro_rules! deps {
    () => {
        MinInt!();
        OtherSign!();
        Int!();
    };
}

macro_rules! Float {
    () => {
        deps!();
        # [doc = " Trait for some basic operations on floats"] # [allow (dead_code)] pub trait Float : Copy + fmt :: Debug + PartialEq + PartialOrd + ops :: AddAssign + ops :: MulAssign + ops :: Add < Output = Self > + ops :: Sub < Output = Self > + ops :: Mul < Output = Self > + ops :: Div < Output = Self > + ops :: Rem < Output = Self > + ops :: Neg < Output = Self > + 'static { # [doc = " A uint of the same width as the float"] type Int : Int < OtherSign = Self :: SignedInt , Unsigned = Self :: Int > ; # [doc = " A int of the same width as the float"] type SignedInt : Int + MinInt < OtherSign = Self :: Int , Unsigned = Self :: Int > + ops :: Neg < Output = Self :: SignedInt > ; const ZERO : Self ; const NEG_ZERO : Self ; const ONE : Self ; const NEG_ONE : Self ; const INFINITY : Self ; const NEG_INFINITY : Self ; const NAN : Self ; const NEG_NAN : Self ; const MAX : Self ; const MIN : Self ; const EPSILON : Self ; const PI : Self ; const NEG_PI : Self ; const FRAC_PI_2 : Self ; const MIN_POSITIVE_NORMAL : Self ; # [doc = " The bitwidth of the float type"] const BITS : u32 ; # [doc = " The bitwidth of the significand"] const SIG_BITS : u32 ; # [doc = " The bitwidth of the exponent"] const EXP_BITS : u32 = Self :: BITS - Self :: SIG_BITS - 1 ; # [doc = " The saturated (maximum bitpattern) value of the exponent, i.e. the infinite"] # [doc = " representation."] # [doc = ""] # [doc = " This shifted fully right, use `EXP_MASK` for the shifted value."] const EXP_SAT : u32 = (1 << Self :: EXP_BITS) - 1 ; # [doc = " The exponent bias value"] const EXP_BIAS : u32 = Self :: EXP_SAT >> 1 ; # [doc = " Maximum unbiased exponent value."] const EXP_MAX : i32 = Self :: EXP_BIAS as i32 ; # [doc = " Minimum *NORMAL* unbiased exponent value."] const EXP_MIN : i32 = - (Self :: EXP_MAX - 1) ; # [doc = " Minimum subnormal exponent value."] const EXP_MIN_SUBNORM : i32 = Self :: EXP_MIN - Self :: SIG_BITS as i32 ; # [doc = " A mask for the sign bit"] const SIGN_MASK : Self :: Int ; # [doc = " A mask for the significand"] const SIG_MASK : Self :: Int ; # [doc = " A mask for the exponent"] const EXP_MASK : Self :: Int ; # [doc = " The implicit bit of the float format"] const IMPLICIT_BIT : Self :: Int ; # [doc = " Returns `self` transmuted to `Self::Int`"] fn to_bits (self) -> Self :: Int ; # [doc = " Returns `self` transmuted to `Self::SignedInt`"] # [allow (dead_code)] fn to_bits_signed (self) -> Self :: SignedInt { self . to_bits () . signed () } # [doc = " Check bitwise equality."] # [allow (dead_code)] fn biteq (self , rhs : Self) -> bool { self . to_bits () == rhs . to_bits () } # [doc = " Checks if two floats have the same bit representation. *Except* for NaNs! NaN can be"] # [doc = " represented in multiple different ways."] # [doc = ""] # [doc = " This method returns `true` if two NaNs are compared. Use [`biteq`](Self::biteq) instead"] # [doc = " if `NaN` should not be treated separately."] # [allow (dead_code)] fn eq_repr (self , rhs : Self) -> bool { if self . is_nan () && rhs . is_nan () { true } else { self . biteq (rhs) } } # [doc = " Returns true if the value is NaN."] fn is_nan (self) -> bool ; # [doc = " Returns true if the value is +inf or -inf."] fn is_infinite (self) -> bool ; # [doc = " Returns true if the sign is negative. Extracts the sign bit regardless of zero or NaN."] fn is_sign_negative (self) -> bool ; # [doc = " Returns true if the sign is positive. Extracts the sign bit regardless of zero or NaN."] fn is_sign_positive (self) -> bool { ! self . is_sign_negative () } # [doc = " Returns if `self` is subnormal."] # [allow (dead_code)] fn is_subnormal (self) -> bool { (self . to_bits () & Self :: EXP_MASK) == Self :: Int :: ZERO } # [doc = " Returns the exponent, not adjusting for bias, not accounting for subnormals or zero."] fn ex (self) -> u32 { u32 :: cast_from (self . to_bits () >> Self :: SIG_BITS) & Self :: EXP_SAT } # [doc = " Extract the exponent and adjust it for bias, not accounting for subnormals or zero."] fn exp_unbiased (self) -> i32 { self . ex () . signed () - (Self :: EXP_BIAS as i32) } # [doc = " Returns the significand with no implicit bit (or the \"fractional\" part)"] # [allow (dead_code)] fn frac (self) -> Self :: Int { self . to_bits () & Self :: SIG_MASK } # [doc = " Returns a `Self::Int` transmuted back to `Self`"] fn from_bits (a : Self :: Int) -> Self ; # [doc = " Constructs a `Self` from its parts. Inputs are treated as bits and shifted into position."] fn from_parts (negative : bool , exponent : u32 , significand : Self :: Int) -> Self { let sign = if negative { Self :: Int :: ONE } else { Self :: Int :: ZERO } ; Self :: from_bits ((sign << (Self :: BITS - 1)) | (Self :: Int :: cast_from (exponent & Self :: EXP_SAT) << Self :: SIG_BITS) | (significand & Self :: SIG_MASK) ,) } # [allow (dead_code)] fn abs (self) -> Self ; # [doc = " Returns a number composed of the magnitude of self and the sign of sign."] fn copysign (self , other : Self) -> Self ; # [doc = " Fused multiply add, rounding once."] fn fma (self , y : Self , z : Self) -> Self ; # [doc = " Returns (normalized exponent, normalized significand)"] # [allow (dead_code)] fn normalize (significand : Self :: Int) -> (i32 , Self :: Int) ; # [doc = " Returns a number that represents the sign of self."] # [allow (dead_code)] fn signum (self) -> Self { if self . is_nan () { self } else { Self :: ONE . copysign (self) } } # [doc = " Make a best-effort attempt to canonicalize the number. Note that this is allowed"] # [doc = " to be a nop and does not always quiet sNaNs."] fn canonicalize (self) -> Self { self * Self :: ONE } }
    };
}

Float!();